74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
81	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
82	     * addresses are lower-cased before being stored.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
86	
87	    /** An owner's postcode, when supplied, must be exactly four digits. */
88	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
89	
90	    /**
91	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
92	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
93	     */
94	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
95	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
96	
97	    /**
98	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
99	     * named logger keeps them addressable independently of the class's diagnostic logging.
100	     */
101	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
102	
103	    /**
104	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
105	     * audit event. It is process-wide (static) so the ordering holds across every owner created,
106	     * regardless of which controller instance handles the request.
107	     */
108	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong(0);
109	
110	    /** Serializes the immutable structured audit event to its canonical JSON representation. */
111	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
112	
113	    /**
114	     * Maximum number of owners a single city may contain. A create that would take the owner's city
115	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
116	     */
117	    private static final int CITY_OWNER_LIMIT = 50;
118	
119	    /**
120	     * Number of owners a city must already hold for a create response and owner read to flag that the
121	     * city is approaching capacity. When the city holds between this many and {@link #CITY_OWNER_LIMIT}
122	     * minus one owners (40-49), the owner's {@code capacityWarning} is {@code true}; the hard rejection
123	     * at {@link #CITY_OWNER_LIMIT} is unchanged.
124	     */
125	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
126	
127	    /**
128	     * Maximum number of owners that may be registered on a single day. A create that would take the
129	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
130	     * have already been created that day - is rejected with a 429.
131	     */
132	    private static final int DAILY_OWNER_LIMIT = 100;
133	
134	    /**
135	     * Number of owners that must already have been created for a given day before the create
136	     * response flags a bulk sign-up. When more than this many owners already share a
137	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
138	     */
139	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
140	
141	    /**
142	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
143	     * like a weekend and rolled forward to the next non-holiday business day.
144	     */
145	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
146	        LocalDate.of(2026, 1, 1),
147	        LocalDate.of(2026, 1, 26),
148	        LocalDate.of(2026, 4, 25),
149	        LocalDate.of(2026, 12, 25),
150	        LocalDate.of(2026, 12, 28));
151	
152	    /**
153	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
154	     * already seen, the originally created owner is returned instead of creating a duplicate.
155	     */
156	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
157	
158	    private final ClinicService clinicService;
159	
160	    private final OwnerMapper ownerMapper;
161	
162	    private final PetMapper petMapper;
163	
164	    private final VisitMapper visitMapper;
165	
166	    private final HttpServletRequest request;
167	
168	    /**
169	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
170	     * create with an already-seen key returns the originally created owner rather than a duplicate.
171	     */
172	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
173	
174	    public OwnerRestControllerV1(ClinicService clinicService,
175	                                 OwnerMapper ownerMapper,
176	                                 PetMapper petMapper,
177	                                 VisitMapper visitMapper,
178	                                 HttpServletRequest request) {
179	        this.clinicService = clinicService;
180	        this.ownerMapper = ownerMapper;
181	        this.petMapper = petMapper;
182	        this.visitMapper = visitMapper;
183	        this.request = request;
184	    }
