186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
189	        Collection<Owner> owners;
190	        if (lastName != null) {
191	            owners = this.clinicService.findOwnerByLastName(lastName);
192	        } else {
193	            owners = this.clinicService.findAllOwners();
194	        }
195	        if (owners.isEmpty()) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
209	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
210	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
211	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
212	    }
213	
214	    /**
215	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
216	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
217	     * owner sign-ups.
218	     *
219	     * @param registrationDate the day to inspect, or {@code null}
220	     * @return {@code true} when more than the threshold of owners are registered on that day
221	     */
222	    private boolean isBulkSignupDay(LocalDate registrationDate) {
223	        return registrationDate != null
224	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
225	    }
226	
227	    /**
228	     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
229	     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
230	     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
231	     * rejection is unchanged.
232	     *
233	     * @param city the city to inspect, or {@code null}
234	     * @return {@code true} when the city holds 40-49 owners
235	     */
236	    private boolean isApproachingCityCapacity(String city) {
237	        if (city == null) {
238	            return false;
239	        }
240	        long count = countOwnersInCity(city);
241	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
247	        String idempotencyKey = idempotencyKey();
248	        if (idempotencyKey != null) {
249	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
250	            if (existing != null) {
251	                return new ResponseEntity<>(existing, HttpStatus.OK);
252	            }
253	        }
254	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
255	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
256	        finalizeOwnerForCreate(owner);
257	        this.clinicService.saveOwner(owner);
258	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
259	        if (idempotencyKey != null) {
260	            this.idempotencyStore.put(idempotencyKey, response.getBody());
261	        }
262	        return response;
263	    }
264	
265	    /**
266	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
267	     * when the header is absent or blank.
268	     */
269	    private String idempotencyKey() {
270	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
271	        return StringUtils.hasText(key) ? key : null;
272	    }
273	
274	    /**
275	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
276	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
277	     * submitted address is canonicalized, the required fields and the optional postcode and
278	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
279	     * registration date is defaulted to the server date when absent and rolled forward to a business
280	     * day. The household id and identity key are derived; a create whose identity key matches an
281	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
282	     * and otherwise a soft-match duplicate is flagged.
283	     *
284	     * @param ownerFieldsDto the submitted owner fields
285	     * @return the normalized owner, not yet persisted
286	     */
287	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
288	        resolveAddressFields(ownerFieldsDto);
289	        validateRequiredFields(ownerFieldsDto);
290	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
291	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
292	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
293	        owner.setEmail(normalizeEmail(owner.getEmail()));
294	        validateRegistrationDate(owner.getRegistrationDate());
295	        if (owner.getRegistrationDate() == null) {
296	            owner.setRegistrationDate(LocalDate.now());
297	        }
298	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
299	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
300	        resolveHouseholdIdentity(owner, sharesHousehold);
301	        return owner;
302	    }
303	
304	    /**
305	     * Places the owner about to be created into its household and settles its identity against the
306	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
307	     * its last name and postcode (it drives the household size and membership-level cap), but identity
308	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
309	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
310	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
311	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
312	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
313	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
314	     * rather than rejected, with their membership level later capped by
315	     * {@link #applyMembershipLevelCap(Owner)}.
316	     *
317	     * @param owner the normalized owner about to be created, with its contact details already normalized
318	     * @param sharesHousehold whether the request opted into joining an existing household
319	     */
320	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
321	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
322	        owner.setIdentityKey(buildIdentityKey(owner));
323	        if (!sharesHousehold) {
324	            rejectDuplicateIdentity(owner);
325	        }
326	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
327	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
328	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
329	    }
330	
331	    /**
332	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
333	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
334	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
335	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
336	     * registration date, measured before it is saved, which the caller uses to decide the response's
337	     * {@code bulkSignupWarning}.
338	     *
339	     * @param owner the normalized owner about to be created
340	     * @return the number of owners already registered on the owner's registration date
341	     */
342	    private long enforceCreateLimits(Owner owner) {
343	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
344	            throw new OwnerCityFullException(owner.getCity());
345	        }
346	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
347	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
348	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
349	        }
350	        return ownersRegisteredOnDay;
351	    }
352	
353	    /**
354	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
355	     * de-duplicated customer code, the number of existing namesakes, the household size once the
356	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
357	     *
358	     * @param owner the normalized owner about to be created
359	     */
360	    private void finalizeOwnerForCreate(Owner owner) {
361	        owner.setCustomerCode(buildCustomerCode(owner));
362	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
363	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
364	        applyMembershipLevelCap(owner);
365	    }
366	
367	    /**
368	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
369	     * current maximum membership level among the owner's existing household members. The owner is not
370	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
371	     * file; each member's effective (already-capped) level is read via
372	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
373	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
374	     * its fully-derived level.
375	     *
376	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
377	     */
378	    private void applyMembershipLevelCap(Owner owner) {
379	        activeHouseholdMembers(owner.getHouseholdId()).stream()
380	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
381	            .max()
382	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
383	    }
384	
385	    /**
386	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
387	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
388	     * count, and adds the {@code Location} header pointing at the new owner.
389	     *
390	     * @param owner the owner that has just been saved, with its generated id populated
391	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
392	     * @return the created-owner response
393	     */
394	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
395	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
396	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
397	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
398	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
399	        emitOwnerCreatedEvent(owner, ownerDto);
400	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
401	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
402	        HttpHeaders headers = new HttpHeaders();
403	        headers.setLocation(UriComponentsBuilder.newInstance()
404	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
405	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
406	    }
407	
408	    /**
409	     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
410	     * alongside the human-readable audit line. The event is a JSON object
411	     * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code seq} is a
412	     * process-wide, monotonically increasing sequence across all creates. Its {@code customerCode}
413	     * field carries the owner's <em>current primary identifier</em> - the customer code today, and
414	     * whatever supersedes it later (for instance the member id once the two are unified) - as
415	     * returned by {@link #primaryIdentifier(Owner)}.
416	     *
417	     * @param owner the owner that has just been saved, with its generated id populated
418	     * @param ownerDto the mapped DTO, source of the derived membership level
419	     */
420	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
421	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
422	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
423	        try {
424	            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
425	        }
426	        catch (JacksonException e) {
427	            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
428	        }
429	    }
430	
431	    /**
432	     * Returns the owner's current primary identifier - the value the structured audit event carries
433	     * as its {@code customerCode}. Today that is the owner's customer code; when the customer code is
434	     * later unified into the member id, this is the single place that changes so the emitted event
435	     * carries the member id instead.
436	     *
437	     * @param owner the owner whose primary identifier is required
438	     * @return the owner's current primary identifier
439	     */
440	    private String primaryIdentifier(Owner owner) {
441	        return owner.getCustomerCode();
442	    }
443	
444	    /**
445	     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code customerCode}
446	     * field holds the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
447	     */
448	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
449	        Integer membershipLevel, String event) {
450	    }
451	
452	    /**
453	     * Canonicalizes the submitted address fields into the form that is validated, stored and
454	     * returned, before any required-field check or mapping runs. This is the single place a create
455	     * request's address input is resolved.
456	     *
457	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
458	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
459	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
460	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
461	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
462	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
463	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
464	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
465	     * that is blank only after normalization is left blank here and rejected later by
466	     * {@link #validateRequiredFields}.
467	     *
468	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
469	     */
470	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
471	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
472	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
473	        if (!line1.isEmpty()) {
474	            ownerFieldsDto.setAddressLine1(line1);
475	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
476	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
477	        }
478	        else {
479	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
480	        }
481	    }
482	
483	    /**
484	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
485	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
486	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
487	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
488	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
489	     * normalization is still rejected.
490	     *
491	     * @param ownerFieldsDto the submitted owner fields
492	     */
493	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
494	        List<String> missingFields = new ArrayList<>();
495	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
496	            missingFields.add("firstName");
497	        }
498	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
499	            missingFields.add("lastName");
500	        }
501	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
502	            missingFields.add("address");
503	        }
504	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
505	            missingFields.add("city");
506	        }
507	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
508	            missingFields.add("telephone");
509	        }
510	        if (!missingFields.isEmpty()) {
511	            throw new MissingOwnerFieldsException(missingFields);
512	        }
513	    }
514	
515	    /**
516	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
517	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
518	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
519	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
520	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
521	     * whose {@code errors} array lists {@code postcode}.
522	     *
523	     * @param postcode the submitted postcode, or {@code null} when none was supplied
524	     * @param city the owner's city, whose region determines the acceptable postcode range
525	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
526	     */
527	    private void validatePostcode(String postcode, String city) {
528	        if (!StringUtils.hasText(postcode)) {
529	            return;
530	        }
531	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
532	            throw new InvalidOwnerFieldsException(List.of("postcode"));
533	        }
534	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
535	            throw new InvalidOwnerFieldsException(List.of("postcode"));
536	        }
537	    }
538	
539	    /**
540	     * Validates an owner's optional registration date. Registration date is optional, so a missing
541	     * value is accepted (the create later defaults it to the server date). When a value is supplied
542	     * it may not lie in the future: a date later than the server's current date is rejected with a
543	     * 400 whose {@code errors} array lists {@code registrationDate}.
544	     *
545	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
546	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
547	     */
548	    private void validateRegistrationDate(LocalDate registrationDate) {
549	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
550	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
551	        }
552	    }
553	
554	    /**
555	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
556	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
557	     * same person being entered twice. This single identity key is the whole of duplicate detection:
558	     * because the telephone is part of the key, distinct people who merely share a last name and
559	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
560	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
561	     * applied when the email was normalized. A genuine identity collision is reported to the client as
562	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
563	     * {@code sharesHousehold}, in which case it is not performed.
564	     *
565	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
566	     */
567	    private void rejectDuplicateIdentity(Owner owner) {
568	        boolean identityInUse = this.clinicService.findAllOwners().stream()
569	            .filter(existing -> !existing.isDeleted())
570	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
571	        if (identityInUse) {
572	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
573	        }
574	    }
575	
576	    /**
577	     * Returns the owners that currently belong to the household identified by {@code householdId} -
578	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
579	     * because they no longer count as present members, so this is the household as it stands for the
580	     * owner being created. This is the single lookup of a household's current members behind the
581	     * household checks that reason about who is already there.
582	     *
583	     * @param householdId the derived household identifier to look up
584	     * @return the existing, non-deleted owners sharing that household, in no particular order
585	     */
586	    private List<Owner> activeHouseholdMembers(String householdId) {
587	        return this.clinicService.findAllOwners().stream()
588	            .filter(existing -> !existing.isDeleted())
589	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
590	            .collect(Collectors.toList());
591	    }
592	
593	    /**
594	     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
595	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
596	     * and email have already been normalized (the email lower-cased, or the empty string when none was
597	     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
598	     * telephone is part of the key, two owners who differ only in telephone derive different identity
599	     * keys, so they are not the same identity even when they share a household.
600	     *
601	     * @param owner the normalized owner about to be created, with its contact details already normalized
602	     * @return the derived identity key, as 64 lower-case hex characters
603	     */
604	    private String buildIdentityKey(Owner owner) {
605	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
606	        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
607	    }
608	
609	    /**
610	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
611	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
612	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
613	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
614	     * particular, two owners with the same last name and postcode but different telephones now derive
615	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
616	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
617	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
618	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
619	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
620	     *
621	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
622	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
623	     */
624	    private Integer findPossibleDuplicate(Owner owner) {
625	        if (!StringUtils.hasText(owner.getPostcode())) {
626	            return null;
627	        }
628	        String soundex = Soundex.encode(owner.getLastName());
629	        return this.clinicService.findAllOwners().stream()
630	            .filter(existing -> !existing.isDeleted())
631	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
632	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
633	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
634	            .map(Owner::getId)
635	            .filter(id -> id != null)
636	            .min(Integer::compareTo)
637	            .orElse(null);
638	    }
639	
640	    /**
641	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
642	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
643	     * address; the accepted value is lower-cased before it is stored and returned.
644	     *
645	     * @param email the raw email value submitted by the client, or {@code null}
646	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
647	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
648	     */
649	    private String normalizeEmail(String email) {
650	        if (!StringUtils.hasText(email)) {
651	            return email;
652	        }
653	        if (!EMAIL_PATTERN.matcher(email).matches()) {
654	            throw new InvalidOwnerFieldsException(List.of("email"));
655	        }
656	        String normalized = email.toLowerCase();
657	        String domain = normalized.substring(normalized.indexOf('@') + 1);
658	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
659	            throw new InvalidOwnerFieldsException(List.of("email"));
660	        }
661	        return normalized;
662	    }
663	
664	    /**
665	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
666	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
667	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
668	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
669	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
670	     *
671	     * @param owner the normalized owner about to be created
672	     * @return the assigned, de-duplicated customer code
673	     */
674	    private String buildCustomerCode(Owner owner) {
675	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
676	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
677	        return deduplicateCustomerCode(code);
678	    }
679	
680	    /**
681	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
682	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
683	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
684	     *
685	     * @param code the composed customer code, before de-duplication
686	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
687	     */
688	    private String deduplicateCustomerCode(String code) {
689	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
690	            .map(Owner::getCustomerCode)
691	            .filter(existing -> existing != null)
692	            .collect(Collectors.toSet());
693	        if (!existingCodes.contains(code)) {
694	            return code;
695	        }
696	        int suffix = 2;
697	        while (existingCodes.contains(code + "-" + suffix)) {
698	            suffix++;
699	        }
700	        return code + "-" + suffix;
701	    }
702	
703	    /**
704	     * Counts how many owners already exist that share the supplied first and last name, compared
705	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
706	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
707	     *
708	     * @param firstName the submitted owner's first name
709	     * @param lastName the submitted owner's last name
710	     * @return the number of existing owners with the same first and last name, ignoring case
711	     */
712	    private int countNamesakes(String firstName, String lastName) {
713	        return (int) this.clinicService.findAllOwners().stream()
714	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
715	                && lastName.equalsIgnoreCase(existing.getLastName()))
716	            .count();
717	    }
718	
719	    /**
720	     * Counts how many existing owners already belong to the supplied household, identified by its
721	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
722	     * owner is added (this count plus one).
723	     *
724	     * @param householdId the normalized household identifier of the owner being created
725	     * @return the number of existing owners already sharing that {@code householdId}
726	     */
727	    private int countHouseholdMembers(String householdId) {
728	        return (int) this.clinicService.findAllOwners().stream()
729	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
730	            .count();
731	    }
732	
733	    /**
734	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
735	     * enforce the per-city capacity limit when a new owner is created.
736	     *
737	     * @param city the submitted owner's city
738	     * @return the number of existing owners in that city, ignoring case
739	     */
740	    private long countOwnersInCity(String city) {
741	        return this.clinicService.findAllOwners().stream()
742	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
743	            .count();
744	    }
745	
746	    /**
747	     * Counts how many owners have already been created on the supplied registration date. Used to
748	     * enforce the per-day capacity limit when a new owner is created.
749	     *
750	     * @param registrationDate the registration date of the owner being created
751	     * @return the number of existing owners already registered on that date
752	     */
753	    /**
754	     * Rolls a registration date forward to a business day. A registration date must fall on a
755	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
756	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
757	     * returned unchanged. Every value derived from the registration date (such as the membership
758	     * number's year segment) and the daily create-limit therefore use the adjusted date.
759	     *
760	     * @param date the effective registration date, whether supplied or defaulted to the server date
761	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
762	     */
763	    private LocalDate toBusinessDay(LocalDate date) {
764	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
765	            date = date.plusDays(1);
766	        }
767	        return date;
768	    }
769	
770	    private boolean isWeekend(LocalDate date) {
771	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
772	    }
773	
774	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
775	        return this.clinicService.findAllOwners().stream()
776	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
777	            .count();
778	    }
779	
780	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
781	    @Override
782	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
783	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
784	        if (currentOwner == null) {
785	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
786	        }
787	        currentOwner.setAddress(ownerFieldsDto.getAddress());
788	        currentOwner.setCity(ownerFieldsDto.getCity());
789	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
790	        currentOwner.setLastName(ownerFieldsDto.getLastName());
791	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
792	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
793	        this.clinicService.saveOwner(currentOwner);
794	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
795	    }
796	
797	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
798	    @Transactional
799	    @Override
800	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
801	        Owner owner = this.clinicService.findOwnerById(ownerId);
802	        if (owner == null) {
803	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
804	        }
805	        owner.setDeleted(true);
806	        this.clinicService.saveOwner(owner);
807	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
808	    }
809	
810	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
811	    @Override
812	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
813	        Owner owner = this.clinicService.findOwnerById(ownerId);
814	        if (owner == null) {
815	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
816	        }
817	        HttpHeaders headers = new HttpHeaders();
818	        Pet pet = petMapper.toPet(petFieldsDto);
819	        owner.setId(ownerId);
820	        pet.setOwner(owner);
821	        pet.getType().setName(null);
822	        this.clinicService.savePet(pet);
823	        PetDto petDto = petMapper.toPetDto(pet);
824	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
825	            .buildAndExpand(pet.getId()).toUri());
826	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
827	    }
828	
829	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
830	    @Override
831	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
832	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
833	        if (currentOwner != null) {
834	            Pet currentPet = this.clinicService.findPetById(petId);
835	            if (currentPet != null) {
836	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
837	                currentPet.setName(petFieldsDto.getName());
838	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
839	                this.clinicService.savePet(currentPet);
840	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
841	            }
842	        }
843	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
844	    }
845	
846	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
847	    @Override
848	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
849	        HttpHeaders headers = new HttpHeaders();
850	        Visit visit = visitMapper.toVisit(visitFieldsDto);
851	        Pet pet = new Pet();
852	        pet.setId(petId);
853	        visit.setPet(pet);
854	        this.clinicService.saveVisit(visit);
855	        VisitDto visitDto = visitMapper.toVisitDto(visit);
856	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
857	            .buildAndExpand(visit.getId()).toUri());
858	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
859	    }
860	
861	
862	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
863	    @Override
864	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
865	        Owner owner = this.clinicService.findOwnerById(ownerId);
866	        if (owner != null) {
867	            Pet pet = owner.getPet(petId);
868	            if (pet != null) {
869	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
870	            }
871	        }
872	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
873	    }
874	}
