package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.json.JsonMapper;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
import org.springframework.samples.petclinic.mapper.OwnerLocality;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /**
     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
     * addresses are lower-cased before being stored.
     */
    private static final Pattern EMAIL_PATTERN =
        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");

    /** An owner's postcode, when supplied, must be exactly four digits. */
    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");

    /**
     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
     */
    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    /**
     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
     * named logger keeps them addressable independently of the class's diagnostic logging.
     */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /**
     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
     * audit event. It is process-wide (static) so the ordering holds across every owner created,
     * regardless of which controller instance handles the request.
     */
    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong(0);

    /** Serializes the immutable structured audit event to its canonical JSON representation. */
    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();

    /**
     * Maximum number of owners a single city may contain. A create that would take the owner's city
     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
     */
    private static final int CITY_OWNER_LIMIT = 50;

    /**
     * Number of owners a city must already hold for a create response and owner read to flag that the
     * city is approaching capacity. When the city holds between this many and {@link #CITY_OWNER_LIMIT}
     * minus one owners (40-49), the owner's {@code capacityWarning} is {@code true}; the hard rejection
     * at {@link #CITY_OWNER_LIMIT} is unchanged.
     */
    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;

    /**
     * Maximum number of owners that may be registered on a single day. A create that would take the
     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
     * have already been created that day - is rejected with a 429.
     */
    private static final int DAILY_OWNER_LIMIT = 100;

    /**
     * Number of owners that must already have been created for a given day before the create
     * response flags a bulk sign-up. When more than this many owners already share a
     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
     */
    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;

    /**
     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
     * like a weekend and rolled forward to the next non-holiday business day.
     */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    /**
     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
     * already seen, the originally created owner is returned instead of creating a duplicate.
     */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final HttpServletRequest request;

    /**
     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
     * create with an already-seen key returns the originally created owner rather than a duplicate.
     */
    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 HttpServletRequest request) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.request = request;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
    }

    /**
     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
     * owner sign-ups.
     *
     * @param registrationDate the day to inspect, or {@code null}
     * @return {@code true} when more than the threshold of owners are registered on that day
     */
    private boolean isBulkSignupDay(LocalDate registrationDate) {
        return registrationDate != null
            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
    }

    /**
     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
     * rejection is unchanged.
     *
     * @param city the city to inspect, or {@code null}
     * @return {@code true} when the city holds 40-49 owners
     */
    private boolean isApproachingCityCapacity(String city) {
        if (city == null) {
            return false;
        }
        long count = countOwnersInCity(city);
        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        String idempotencyKey = idempotencyKey();
        if (idempotencyKey != null) {
            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
            if (existing != null) {
                return new ResponseEntity<>(existing, HttpStatus.OK);
            }
        }
        Owner owner = buildOwnerToCreate(ownerFieldsDto);
        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
        finalizeOwnerForCreate(owner);
        this.clinicService.saveOwner(owner);
        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
        if (idempotencyKey != null) {
            this.idempotencyStore.put(idempotencyKey, response.getBody());
        }
        return response;
    }

    /**
     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
     * when the header is absent or blank.
     */
    private String idempotencyKey() {
        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
        return StringUtils.hasText(key) ? key : null;
    }

    /**
     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
     * submitted address is canonicalized, the required fields and the optional postcode and
     * registration date are validated, and the mapped owner's telephone and email are normalized. The
     * registration date is defaulted to the server date when absent and rolled forward to a business
     * day. The household id and identity key are derived; a create whose identity key matches an
     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
     * and otherwise a soft-match duplicate is flagged.
     *
     * @param ownerFieldsDto the submitted owner fields
     * @return the normalized owner, not yet persisted
     */
    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
        resolveAddressFields(ownerFieldsDto);
        validateRequiredFields(ownerFieldsDto);
        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
        owner.setEmail(normalizeEmail(owner.getEmail()));
        validateRegistrationDate(owner.getRegistrationDate());
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        resolveHouseholdIdentity(owner, sharesHousehold);
        return owner;
    }

    /**
     * Places the owner about to be created into its household and settles its identity against the
     * owners already on file. The owner's {@code householdId} is still derived deterministically from
     * its last name and postcode (it drives the household size and membership-level cap), but identity
     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
     * different telephones now derive different identity keys, so they are admitted (as a soft match)
     * rather than rejected, with their membership level later capped by
     * {@link #applyMembershipLevelCap(Owner)}.
     *
     * @param owner the normalized owner about to be created, with its contact details already normalized
     * @param sharesHousehold whether the request opted into joining an existing household
     */
    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
        owner.setIdentityKey(buildIdentityKey(owner));
        if (!sharesHousehold) {
            rejectDuplicateIdentity(owner);
        }
        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
        owner.setPossibleDuplicate(possibleDuplicateOf != null);
        owner.setPossibleDuplicateOf(possibleDuplicateOf);
    }

    /**
     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
     * rejected with a 429. The returned count is the number of owners already sharing the owner's
     * registration date, measured before it is saved, which the caller uses to decide the response's
     * {@code bulkSignupWarning}.
     *
     * @param owner the normalized owner about to be created
     * @return the number of owners already registered on the owner's registration date
     */
    private long enforceCreateLimits(Owner owner) {
        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
            throw new OwnerCityFullException(owner.getCity());
        }
        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
            throw new OwnerDailyLimitException(owner.getRegistrationDate());
        }
        return ownersRegisteredOnDay;
    }

    /**
     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
     * de-duplicated customer code, the number of existing namesakes, the household size once the
     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
     *
     * @param owner the normalized owner about to be created
     */
    private void finalizeOwnerForCreate(Owner owner) {
        owner.setCustomerCode(buildCustomerCode(owner));
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
        applyMembershipLevelCap(owner);
    }

    /**
     * Caps the membership level of an owner about to be created so it cannot exceed one above the
     * current maximum membership level among the owner's existing household members. The owner is not
     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
     * file; each member's effective (already-capped) level is read via
     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
     * its fully-derived level.
     *
     * @param owner the normalized owner about to be created, with its {@code householdId} already set
     */
    private void applyMembershipLevelCap(Owner owner) {
        activeHouseholdMembers(owner.getHouseholdId()).stream()
            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
            .max()
            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
    }

    /**
     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
     * count, and adds the {@code Location} header pointing at the new owner.
     *
     * @param owner the owner that has just been saved, with its generated id populated
     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
     * @return the created-owner response
     */
    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
        emitOwnerCreatedEvent(owner, ownerDto);
        ownerDto.setBulkSignupWarning(bulkSignupWarning);
        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
     * alongside the human-readable audit line. The event is a JSON object
     * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code seq} is a
     * process-wide, monotonically increasing sequence across all creates. Its {@code customerCode}
     * field carries the owner's <em>current primary identifier</em> - the customer code today, and
     * whatever supersedes it later (for instance the member id once the two are unified) - as
     * returned by {@link #primaryIdentifier(Owner)}.
     *
     * @param owner the owner that has just been saved, with its generated id populated
     * @param ownerDto the mapped DTO, source of the derived membership level
     */
    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
        try {
            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
        }
        catch (JacksonException e) {
            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
        }
    }

    /**
     * Returns the owner's current primary identifier - the value the structured audit event carries
     * as its {@code customerCode}. Today that is the owner's customer code; when the customer code is
     * later unified into the member id, this is the single place that changes so the emitted event
     * carries the member id instead.
     *
     * @param owner the owner whose primary identifier is required
     * @return the owner's current primary identifier
     */
    private String primaryIdentifier(Owner owner) {
        return owner.getCustomerCode();
    }

    /**
     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code customerCode}
     * field holds the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
     */
    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
        Integer membershipLevel, String event) {
    }

    /**
     * Canonicalizes the submitted address fields into the form that is validated, stored and
     * returned, before any required-field check or mapping runs. This is the single place a create
     * request's address input is resolved.
     *
     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
     * present. When no structured line is supplied the flat {@code address} is normalized in place,
     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
     * that is blank only after normalization is left blank here and rejected later by
     * {@link #validateRequiredFields}.
     *
     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
     */
    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
        if (!line1.isEmpty()) {
            ownerFieldsDto.setAddressLine1(line1);
            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
        }
        else {
            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
        }
    }

    /**
     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
     * normalization is still rejected.
     *
     * @param ownerFieldsDto the submitted owner fields
     */
    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
        List<String> missingFields = new ArrayList<>();
        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
            missingFields.add("firstName");
        }
        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
            missingFields.add("lastName");
        }
        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
            missingFields.add("address");
        }
        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
            missingFields.add("city");
        }
        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
            missingFields.add("telephone");
        }
        if (!missingFields.isEmpty()) {
            throw new MissingOwnerFieldsException(missingFields);
        }
    }

    /**
     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
     * city maps to a known region the postcode must fall within that region's inclusive range (checked
     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
     * whose {@code errors} array lists {@code postcode}.
     *
     * @param postcode the submitted postcode, or {@code null} when none was supplied
     * @param city the owner's city, whose region determines the acceptable postcode range
     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
     */
    private void validatePostcode(String postcode, String city) {
        if (!StringUtils.hasText(postcode)) {
            return;
        }
        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
            throw new InvalidOwnerFieldsException(List.of("postcode"));
        }
        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
            throw new InvalidOwnerFieldsException(List.of("postcode"));
        }
    }

    /**
     * Validates an owner's optional registration date. Registration date is optional, so a missing
     * value is accepted (the create later defaults it to the server date). When a value is supplied
     * it may not lie in the future: a date later than the server's current date is rejected with a
     * 400 whose {@code errors} array lists {@code registrationDate}.
     *
     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
     */
    private void validateRegistrationDate(LocalDate registrationDate) {
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
        }
    }

    /**
     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
     * same person being entered twice. This single identity key is the whole of duplicate detection:
     * because the telephone is part of the key, distinct people who merely share a last name and
     * postcode (but differ in telephone) derive a different key and so are admitted rather than
     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
     * applied when the email was normalized. A genuine identity collision is reported to the client as
     * a 409 Conflict. A request may knowingly bypass this check by opting in with
     * {@code sharesHousehold}, in which case it is not performed.
     *
     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
     */
    private void rejectDuplicateIdentity(Owner owner) {
        boolean identityInUse = this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
        if (identityInUse) {
            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
        }
    }

    /**
     * Returns the owners that currently belong to the household identified by {@code householdId} -
     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
     * because they no longer count as present members, so this is the household as it stands for the
     * owner being created. This is the single lookup of a household's current members behind the
     * household checks that reason about who is already there.
     *
     * @param householdId the derived household identifier to look up
     * @return the existing, non-deleted owners sharing that household, in no particular order
     */
    private List<Owner> activeHouseholdMembers(String householdId) {
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .collect(Collectors.toList());
    }

    /**
     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
     * and email have already been normalized (the email lower-cased, or the empty string when none was
     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
     * telephone is part of the key, two owners who differ only in telephone derive different identity
     * keys, so they are not the same identity even when they share a household.
     *
     * @param owner the normalized owner about to be created, with its contact details already normalized
     * @return the derived identity key, as 64 lower-case hex characters
     */
    private String buildIdentityKey(Owner owner) {
        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
    }

    /**
     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
     * particular, two owners with the same last name and postcode but different telephones now derive
     * different identity keys, so instead of the old hard household-duplicate rejection they surface
     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
     *
     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
     * @return the id of the matching existing owner, or {@code null} when there is no soft match
     */
    private Integer findPossibleDuplicate(Owner owner) {
        if (!StringUtils.hasText(owner.getPostcode())) {
            return null;
        }
        String soundex = Soundex.encode(owner.getLastName());
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
            .map(Owner::getId)
            .filter(id -> id != null)
            .min(Integer::compareTo)
            .orElse(null);
    }

    /**
     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
     * blank value is left untouched. When a value is supplied it must be a syntactically valid
     * address; the accepted value is lower-cased before it is stored and returned.
     *
     * @param email the raw email value submitted by the client, or {@code null}
     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
     */
    private String normalizeEmail(String email) {
        if (!StringUtils.hasText(email)) {
            return email;
        }
        if (!EMAIL_PATTERN.matcher(email).matches()) {
            throw new InvalidOwnerFieldsException(List.of("email"));
        }
        String normalized = email.toLowerCase();
        String domain = normalized.substring(normalized.indexOf('@') + 1);
        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
            throw new InvalidOwnerFieldsException(List.of("email"));
        }
        return normalized;
    }

    /**
     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
     * from the owner's postcode (falling back to its city), and the code itself - region plus the
     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
     *
     * @param owner the normalized owner about to be created
     * @return the assigned, de-duplicated customer code
     */
    private String buildCustomerCode(Owner owner) {
        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
        return deduplicateCustomerCode(code);
    }

    /**
     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
     * the smallest {@code n} of two or more that yields a code no existing owner holds.
     *
     * @param code the composed customer code, before de-duplication
     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
     */
    private String deduplicateCustomerCode(String code) {
        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
            .map(Owner::getCustomerCode)
            .filter(existing -> existing != null)
            .collect(Collectors.toSet());
        if (!existingCodes.contains(code)) {
            return code;
        }
        int suffix = 2;
        while (existingCodes.contains(code + "-" + suffix)) {
            suffix++;
        }
        return code + "-" + suffix;
    }

    /**
     * Counts how many owners already exist that share the supplied first and last name, compared
     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
     * owner is created and is stored on the new owner as its {@code namesakeCount}.
     *
     * @param firstName the submitted owner's first name
     * @param lastName the submitted owner's last name
     * @return the number of existing owners with the same first and last name, ignoring case
     */
    private int countNamesakes(String firstName, String lastName) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
                && lastName.equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /**
     * Counts how many existing owners already belong to the supplied household, identified by its
     * {@code householdId}. Used when creating an owner to determine the household's size once the new
     * owner is added (this count plus one).
     *
     * @param householdId the normalized household identifier of the owner being created
     * @return the number of existing owners already sharing that {@code householdId}
     */
    private int countHouseholdMembers(String householdId) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .count();
    }

    /**
     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
     * enforce the per-city capacity limit when a new owner is created.
     *
     * @param city the submitted owner's city
     * @return the number of existing owners in that city, ignoring case
     */
    private long countOwnersInCity(String city) {
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
            .count();
    }

    /**
     * Counts how many owners have already been created on the supplied registration date. Used to
     * enforce the per-day capacity limit when a new owner is created.
     *
     * @param registrationDate the registration date of the owner being created
     * @return the number of existing owners already registered on that date
     */
    /**
     * Rolls a registration date forward to a business day. A registration date must fall on a
     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
     * returned unchanged. Every value derived from the registration date (such as the membership
     * number's year segment) and the daily create-limit therefore use the adjusted date.
     *
     * @param date the effective registration date, whether supplied or defaulted to the server date
     * @return the same date when it is a business day, otherwise the next non-holiday weekday
     */
    private LocalDate toBusinessDay(LocalDate date) {
        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private boolean isWeekend(LocalDate date) {
        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
    }

    private long countOwnersRegisteredOn(LocalDate registrationDate) {
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        owner.setDeleted(true);
        this.clinicService.saveOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}

